import { MatchHandle, MatchStatus, MatchResult, PlayerMatchStats } from './match-provider';
import * as fs from 'fs';
import * as path from 'path';

export class MatchMonitor {
  private statusMap: Map<string, MatchStatus> = new Map();
  private resultMap: Map<string, MatchResult> = new Map();
  private intervals: Map<string, NodeJS.Timeout> = new Map();

  startMonitoring(handle: MatchHandle): void {
    this.statusMap.set(handle.id, 'in_progress');
    
    // In a real implementation, this would connect to RLBot's gRPC/WebSocket server
    // or poll a local output JSON file generated by a Python script monitoring the match.
    // Here we simulate the wait and read from a dummy file location.
    
    const interval = setInterval(() => {
      this.checkStatus(handle);
    }, 2000);
    this.intervals.set(handle.id, interval);
  }

  private checkStatus(handle: MatchHandle) {
    const resultDir = path.join(process.env.APPDATA || '', 'rl-manager', 'match-results');
    const resultFile = path.join(resultDir, `result-${handle.config.fixtureId}.json`);

    if (fs.existsSync(resultFile)) {
      try {
        const data = JSON.parse(fs.readFileSync(resultFile, 'utf8'));
        this.statusMap.set(handle.id, 'completed');
        this.resultMap.set(handle.id, this.parseResult(data, handle));
        this.cancelMonitoring(handle.id);
      } catch (err) {
        console.error('Error reading match result', err);
      }
    } else {
      // Check for timeout (e.g. max 15 minutes)
      if (Date.now() - handle.startTime > 15 * 60 * 1000) {
        this.statusMap.set(handle.id, 'failed');
        this.cancelMonitoring(handle.id);
      }
    }
  }

  private parseResult(data: any, handle: MatchHandle): MatchResult {
    // Map raw RLBot JSON output to our unified MatchResult
    return {
      fixtureId: handle.config.fixtureId,
      gameNumber: handle.config.gameNumber,
      blueScore: data.blueScore || 0,
      orangeScore: data.orangeScore || 0,
      blueStats: data.blueStats || [],
      orangeStats: data.orangeStats || [],
      durationSeconds: data.durationSeconds || 300,
      completedAt: Date.now()
    };
  }

  getStatus(matchId: string): MatchStatus {
    return this.statusMap.get(matchId) || 'waiting';
  }

  getResult(matchId: string): MatchResult | null {
    return this.resultMap.get(matchId) || null;
  }

  cancelMonitoring(matchId: string): void {
    const interval = this.intervals.get(matchId);
    if (interval) {
      clearInterval(interval);
      this.intervals.delete(matchId);
    }
  }
}
